(function(){
  'use strict';

  const DISPLAY_DOMAIN='www.tools.adrianheadley.com';
  const SITE_URL='https://tools.adrianheadley.com/';
  const TEMPLATE_DATA="data:image/png;base64,";

  function ensureJsPdf(){
    if(!window.jspdf?.jsPDF){
      throw new Error('PDF export library could not load. Please refresh the page and try again.');
    }
    return window.jspdf.jsPDF;
  }

  function addSiteLink(doc,x,y,w,h){
    try{
      doc.link(x,y,w,h,{url:SITE_URL});
    }catch(_){
    }
  }

  function applyTemplateToCurrentPage(doc,pageNumber){
    const width=doc.internal.pageSize.getWidth();
    const height=doc.internal.pageSize.getHeight();

    // Exact full-page render of the user's attached PDF template.
    // Header and watermark are already baked into this image at the exact
    // strength, colour, size and position supplied by the user.
    doc.addImage(
      TEMPLATE_DATA,
      'PNG',
      0,
      0,
      width,
      height,
      'tools-user-pdf-template-exact',
      'FAST'
    );

    // Clickable overlay over the header/logo/address area.
    addSiteLink(doc,13,7,120,23);

    // Only the page number is dynamic; the rest follows the supplied template.
    doc.setFont('helvetica','normal');
    doc.setFontSize(7.5);
    doc.setTextColor(148,163,184);

    const footerText=`${DISPLAY_DOMAIN} · Page | ${pageNumber}`;
    doc.text(footerText,width/2,height-19.5,{align:'center'});

    try{
      const footerWidth=doc.getTextWidth(footerText);
      addSiteLink(doc,(width-footerWidth)/2,height-24,footerWidth,8);
    }catch(_){
    }
  }

  function createPageController(doc){
    let pageNumber=1;
    applyTemplateToCurrentPage(doc,pageNumber);

    return {
      newPage(){
        doc.addPage();
        pageNumber+=1;
        applyTemplateToCurrentPage(doc,pageNumber);
        return 39;
      }
    };
  }

  function ensureRoom(doc,pages,y,needed=7){
    const pageHeight=doc.internal.pageSize.getHeight();
    if(y+needed>pageHeight-22){
      return pages.newPage();
    }
    return y;
  }

  function drawDocumentTitle(doc,pages,{title='',subtitle='',metaLines=[]}={}){
    const width=doc.internal.pageSize.getWidth();
    const margin=18;
    let y=38;

    if(title){
      doc.setFont('helvetica','bold');
      doc.setFontSize(15);
      doc.setTextColor(17,24,39);
      const lines=doc.splitTextToSize(String(title),width-(margin*2));
      doc.text(lines,margin,y);
      y+=lines.length*6.3+1;
    }

    if(subtitle){
      doc.setFont('helvetica','bold');
      doc.setFontSize(10.5);
      doc.setTextColor(37,99,235);
      const lines=doc.splitTextToSize(String(subtitle),width-(margin*2));
      doc.text(lines,margin,y);
      y+=lines.length*5+1;
    }

    const details=[
      ...((Array.isArray(metaLines)?metaLines:[]).filter(Boolean)),
      `Generated ${new Date().toLocaleString('en-GB')}`
    ];

    if(details.length){
      doc.setFont('helvetica','normal');
      doc.setFontSize(8);
      doc.setTextColor(100,116,139);

      details.forEach(line=>{
        y=ensureRoom(doc,pages,y,5);
        doc.text(String(line),margin,y);
        y+=4.2;
      });
    }

    doc.setDrawColor(226,232,240);
    doc.line(margin,y+1,width-margin,y+1);
    return y+7;
  }

  function drawTextBody(doc,pages,text,startY){
    const width=doc.internal.pageSize.getWidth();
    const margin=18;
    let y=startY;

    const source=String(text??'').replace(/\r\n/g,'\n').split('\n');

    for(const rawLine of source){
      const line=String(rawLine);

      if(!line.trim()){
        y+=3.4;
        y=ensureRoom(doc,pages,y,5);
        continue;
      }

      const headingLike=/^[^:]{1,64}:$/.test(line.trim());

      if(headingLike){
        y=ensureRoom(doc,pages,y,10);
        doc.setFont('helvetica','bold');
        doc.setFontSize(10.5);
        doc.setTextColor(17,24,39);
        doc.text(line.trim().replace(/:$/,''),margin,y);
        y+=5.4;
        continue;
      }

      doc.setFont('helvetica','normal');
      doc.setFontSize(9.1);
      doc.setTextColor(55,65,81);

      const wrapped=doc.splitTextToSize(line,width-(margin*2));

      for(const part of wrapped){
        y=ensureRoom(doc,pages,y,5);
        doc.setFont('helvetica','normal');
        doc.setFontSize(9.1);
        doc.setTextColor(55,65,81);
        doc.text(part,margin,y);
        y+=4.6;
      }
    }

    return y;
  }

  function triggerPdfDownload(doc,filename){
    const blob=doc.output('blob');
    const url=URL.createObjectURL(blob);
    const link=document.createElement('a');

    link.href=url;
    link.download=filename||'export.pdf';
    link.style.display='none';

    document.body.appendChild(link);
    link.click();
    link.remove();

    setTimeout(()=>URL.revokeObjectURL(url),4000);
  }

  function saveTextPdf({
    text='',
    title='PDF Export',
    subtitle='',
    metaLines=[],
    filename='export.pdf'
  }={}){
    const jsPDF=ensureJsPdf();

    const doc=new jsPDF({
      orientation:'portrait',
      unit:'mm',
      format:'a4',
      compress:true
    });

    const pages=createPageController(doc);
    const y=drawDocumentTitle(doc,pages,{title,subtitle,metaLines});
    drawTextBody(doc,pages,text,y);

    triggerPdfDownload(doc,filename);
    return doc;
  }

  function saveCanvasPdf({
    canvas,
    title='PDF Export',
    subtitle='',
    metaLines=[],
    filename='export.pdf'
  }={}){
    if(!(canvas instanceof HTMLCanvasElement)){
      throw new Error('Nothing is available to export as a PDF.');
    }

    const jsPDF=ensureJsPdf();

    const doc=new jsPDF({
      orientation:'portrait',
      unit:'mm',
      format:'a4',
      compress:true
    });

    const pages=createPageController(doc);
    const width=doc.internal.pageSize.getWidth();
    const height=doc.internal.pageSize.getHeight();
    const margin=18;
    const y=drawDocumentTitle(doc,pages,{title,subtitle,metaLines});

    const imageData=canvas.toDataURL('image/png');
    const maxW=width-(margin*2);
    const maxH=(height-24)-y;
    const aspect=canvas.width/canvas.height;

    let drawW=maxW;
    let drawH=drawW/aspect;

    if(drawH>maxH){
      drawH=maxH;
      drawW=drawH*aspect;
    }

    const x=(width-drawW)/2;
    doc.addImage(imageData,'PNG',x,y,drawW,drawH,'tools-export-content','FAST');

    triggerPdfDownload(doc,filename);
    return doc;
  }

  window.ToolsPDFExport={
    DISPLAY_DOMAIN,
    SITE_URL,
    saveTextPdf,
    saveCanvasPdf
  };
})();
